import { computed, toValue } from 'vue'
import type { MaybeRefOrGetter } from 'vue'
import { useQuery } from '@tanstack/vue-query'

export interface CatalogFilters {
  category?: string
  search?: string
}

export interface CatalogItem {
  id: string
  title: string
  price: number
}

export const catalogQueryKeys = {
  all: ['catalog'] as const,
  list: (filters: CatalogFilters) => [...catalogQueryKeys.all, 'list', filters] as const,
}

async function fetchCatalog(filters: CatalogFilters): Promise<CatalogItem[]> {
  const params = new URLSearchParams(
    Object.entries(filters).filter((entry): entry is [string, string] => entry[1] !== undefined),
  )
  const response = await fetch(`/api/catalog?${params.toString()}`)
  if (!response.ok) {
    throw new Error(`Failed to load catalog: ${response.status}`)
  }
  return (await response.json()) as CatalogItem[]
}

export function useCatalogQuery(filters: MaybeRefOrGetter<CatalogFilters> = {}) {
  const queryKey = computed(() => catalogQueryKeys.list(toValue(filters)))

  return useQuery({
    queryKey,
    queryFn: () => fetchCatalog(toValue(filters)),
  })
}
